create table public.historical_replay_runs(id uuid primary key default gen_random_uuid(),replay_version text not null,ordering_version text not null,status text not null check(status in('PENDING','RUNNING','COMPLETED','FAILED')),starts_at timestamptz not null,ends_at timestamptz not null,current_replay_time timestamptz not null,information_cutoff_policy text not null,dataset_hash text not null,input_hash text not null unique,simulation_run_id uuid references public.simulation_runs(id),items_processed integer not null default 0,last_error text,created_at timestamptz not null default now(),completed_at timestamptz,check(starts_at<ends_at),check(current_replay_time between starts_at and ends_at));
create table public.historical_replay_items(id uuid primary key default gen_random_uuid(),replay_run_id uuid not null references public.historical_replay_runs(id),sequence_number integer not null,item_kind text not null,source_id text not null,asset_id uuid references public.assets(id),entity_id text not null,occurred_at timestamptz not null,available_at timestamptz not null,replayed_at timestamptz not null,summary text not null,state text,data_quality numeric,evidence_refs jsonb not null default'[]',item_hash text not null,created_at timestamptz not null default now(),check(available_at<=replayed_at),unique(replay_run_id,sequence_number),unique(replay_run_id,item_kind,source_id));
create table public.historical_replay_checkpoints(id uuid primary key default gen_random_uuid(),replay_run_id uuid not null references public.historical_replay_runs(id),sequence_number integer not null,replay_time timestamptz not null,information_available_through timestamptz not null,state jsonb not null,state_hash text not null,created_at timestamptz not null default now(),check(information_available_through<=replay_time),unique(replay_run_id,sequence_number));
create index historical_replay_items_timeline_idx on public.historical_replay_items(replay_run_id,sequence_number);create index historical_replay_runs_recent_idx on public.historical_replay_runs(created_at desc);
create or replace function public.prevent_historical_replay_mutation()returns trigger language plpgsql as $$begin raise exception'Historical replay history is immutable';end$$;
create trigger historical_replay_items_immutable before update or delete on public.historical_replay_items for each row execute function public.prevent_historical_replay_mutation();create trigger historical_replay_checkpoints_immutable before update or delete on public.historical_replay_checkpoints for each row execute function public.prevent_historical_replay_mutation();
alter table public.historical_replay_runs enable row level security;alter table public.historical_replay_items enable row level security;alter table public.historical_replay_checkpoints enable row level security;
create policy "public read replay runs" on public.historical_replay_runs for select using(true);create policy "public read replay items" on public.historical_replay_items for select using(true);create policy "public read replay checkpoints" on public.historical_replay_checkpoints for select using(true);
grant select on public.historical_replay_runs,public.historical_replay_items,public.historical_replay_checkpoints to anon,authenticated;grant all on public.historical_replay_runs,public.historical_replay_items,public.historical_replay_checkpoints to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure','simulation','historical_replay'));
